-- Vidéos à refaire, à charger dans D1 une fois leurs vidéos déposées dans R2 (bucket studio-files) :
--   pnpm --filter @studio/api exec wrangler d1 execute DB --remote --file seeds/templates.sql -c wrangler.jsonc
-- Rejouable (INSERT OR REPLACE). Chaque vidéo : templates/<id>/video.mp4, aperçu en H.264 720p sans le son (moins de 2 Mo),
-- lu par tous les navigateurs (les originaux en HEVC ne le sont pas partout). Ordre d'affichage : `sort`.
-- `image` : consigne de l'image de départ (Krea 3) que le modèle vidéo anime ; `plans` : [{ text, dur }] ; `photo` : ce que l'utilisateur ajoute comme image de départ (NULL : texte seul).
INSERT OR REPLACE INTO templates (id, name, blurb, category, video_key, image, model_id, plans, resolution, ratio, sound, photo, sort, published, created_at) VALUES
('explainer-produit', 'Explainer produit', 'Votre produit s''ouvre en vue éclatée, pièce par pièce, en rendu studio', 'produit', 'templates/explainer-produit/video.mp4', 'Photo studio du produit de la photo, posé seul au centre d''un fond beige uni, lumière douce et ombre légère, rendu 3D net, format paysage.', 'kling-4',
 '[{"text":"Plan studio sur fond beige uni. Le produit de la photo est posé au centre, puis s''ouvre et ses pièces s''écartent en vue éclatée, flottant dans l''air ; des contours lumineux soulignent les composants, puis tout se referme. Lumière douce, rendu 3D net, caméra qui tourne lentement autour.","dur":12}]',
 '1080p', '16:9', 1, 'Une photo de votre produit', 10, 1, unixepoch() * 1000),
('produit-en-main', 'Produit en main', 'Une créatrice présente votre produit face caméra, en vidéo verticale', 'pub', 'templates/produit-en-main/video.mp4', 'Photo verticale façon créatrice de contenu : une jeune femme souriante dans une pièce claire tient le produit de la photo à hauteur de poitrine, face caméra. Garder le produit exactement tel quel.', 'flux-3-max',
 '[{"text":"Vidéo verticale façon créatrice de contenu : une jeune femme souriante, face caméra, dans une pièce claire, tient le produit de la photo, le montre de près, le tourne dans ses mains et le présente fièrement. Lumière naturelle, rythme vif, ambiance joyeuse.","dur":8}]',
 '1080p', '9:16', 1, 'Une photo de votre produit', 20, 1, unixepoch() * 1000),
('sac-porte', 'Sac porté', 'Un sac porté devant une colonnade, en vidéo verticale façon réseaux', 'pub', 'templates/sac-porte/video.mp4', 'Photo verticale en pied : une jeune femme en pull marine et jean devant une colonnade, feuilles d''automne au sol, tient le sac de la photo devant elle. Garder le sac exactement tel quel.', 'flux-3-max',
 '[{"text":"Vidéo verticale, plan fixe en pied devant une colonnade, feuilles d''automne au sol. Une jeune femme en pull marine et jean tient le sac de la photo, le lève à hauteur de poitrine, le montre fièrement et sourit à la caméra. Lumière naturelle douce.","dur":8}]',
 '1080p', '9:16', 1, 'Une photo de votre sac', 30, 1, unixepoch() * 1000),
('shaker-cuisine', 'Shaker en cuisine', 'Un sportif prépare son shaker avec votre produit, face caméra', 'pub', 'templates/shaker-cuisine/video.mp4', 'Photo verticale : un homme musclé en t-shirt kaki dans une cuisine ensoleillée, le produit de la photo posé sur le plan de travail à côté d''un shaker. Garder le produit exactement tel quel.', 'flux-3-max',
 '[{"text":"Vidéo verticale dans une cuisine ensoleillée. Un homme musclé en t-shirt kaki verse une dose du produit de la photo dans son shaker, le secoue avec énergie puis le montre à la caméra avec un sourire. Rayons de soleil sur le plan de travail, ambiance matinale.","dur":8}]',
 '1080p', '9:16', 1, 'Une photo de votre produit', 40, 1, unixepoch() * 1000),
('pub-boisson', 'Pub boisson pastel', 'Une pub colorée : des amies partagent votre boisson, puis le produit en vedette', 'pub', 'templates/pub-boisson/video.mp4', 'Photo publicitaire pastel rose et pêche : une jeune femme à frange en tenue corail tient la boisson de la photo avec une paille, regard malicieux. Garder l''emballage exactement tel quel.', 'kling-4',
 '[{"text":"Univers pastel rose et pêche. Gros plan : une jeune femme à frange plante une paille dans la brique de la photo, regard malicieux.","dur":5},{"text":"Quatre amies en tenues corail marchent dans une ruelle pastel, puis boivent ensemble à la paille en riant, joue contre joue.","dur":5},{"text":"Plan produit : la brique de la photo posée sur un socle blanc à côté d''un fruit, fond crème, lumière de studio.","dur":5}]',
 '1080p', '16:9', 1, 'Une photo de votre boisson', 50, 1, unixepoch() * 1000),
('coach-accessoire', 'Coach et accessoire', 'Un coach présente votre accessoire en salle de sport, puis le met en action', 'pub', 'templates/coach-accessoire/video.mp4', 'Photo verticale dans une grande salle de sport : un coach barbu en survêtement beige tient le produit de la photo devant lui, face caméra. Garder le produit exactement tel quel.', 'flux-3-max',
 '[{"text":"Vidéo verticale dans une grande salle de sport. Un coach barbu en survêtement beige tient le produit de la photo, le présente à la caméra en parlant avec enthousiasme, puis l''utilise pour quelques tractions. Ton dynamique, lumière industrielle.","dur":10}]',
 '1080p', '9:16', 1, 'Une photo de votre produit', 60, 1, unixepoch() * 1000),
('scene-de-film', 'Scène de film', 'Trois plans de comédie : la colère au bureau, puis le calme sur un yacht', 'cinema', 'templates/scene-de-film/video.mp4', 'Image de cinéma : la personne de la photo, chemise bleue et cravate, dans une salle de marchés des années 80 avec écrans de cotations rouges et verts. Garder son visage.', 'kling-4',
 '[{"text":"Salle de marchés des années 80, écrans de cotations rouges et verts. Le personnage de la photo, chemise bleue et cravate, avance d''un pas décidé entre les bureaux pendant que ses collègues le regardent.","dur":4},{"text":"Il soulève une photocopieuse au-dessus de sa tête et la jette ; les feuilles volent, la salle est figée. Gros plan sur son regard furieux.","dur":4},{"text":"Sur le pont d''un yacht en pleine mer, calme, il boit un expresso au soleil puis contemple le sillage. Ton de comédie, image de cinéma.","dur":4}]',
 '1080p', '16:9', 1, 'Une photo du personnage', 70, 1, unixepoch() * 1000),
('scene-action', 'Scène d''action', 'Une ruelle néon, un sourire, puis une bagarre sous la pluie', 'cinema', 'templates/scene-action/video.mp4', 'Image de cinéma de nuit : la personne de la photo dans une ruelle de Tokyo éclairée de néons rouges, vapeur, passants en capuche, sourire en coin. Garder son visage.', 'kling-4',
 '[{"text":"Nuit, ruelle de Tokyo éclairée de néons rouges, vapeur et passants en capuche. Le personnage de la photo avance vers la caméra, sourire en coin.","dur":5},{"text":"Il est attaqué par une silhouette en imperméable noir : bagarre rapide sous la pluie, chute dans des caisses en plastique. Caméra à l''épaule, style film d''action.","dur":5}]',
 '1080p', '16:9', 1, 'Une photo du personnage', 80, 1, unixepoch() * 1000),
('portrait-cinema', 'Portrait de cinéma', 'Un regard caméra dans un métro bondé, lumière néon et grain de film', 'cinema', 'templates/portrait-cinema/video.mp4', 'Image de cinéma : la personne de la photo debout contre la barre dans une rame de métro bondée le soir, regard caméra, foule floue, néon froid, grain de film. Garder son visage.', 'kling-4',
 '[{"text":"Plan cinéma dans une rame de métro bondée, le soir. La personne de la photo, debout contre la barre, regarde la caméra, ajuste ses lunettes et esquisse un sourire pendant que la foule passe floue autour d''elle. Lumière néon froide, faible profondeur de champ, grain de film.","dur":15}]',
 '1080p', '16:9', 1, 'Une photo de la personne', 90, 1, unixepoch() * 1000),
('chien-brushing', 'Brushing du chien', 'Un chiot passe au séchoir et en ressort avec une coiffure énorme', 'animaux', 'templates/chien-brushing/video.mp4', 'Photo : l''animal de la photo assis sur une table de toilettage dans un salon vert d''eau aux lumières dorées, une toiletteuse tient un séchoir. Garder l''animal tel quel.', 'kling-4',
 '[{"text":"Salon de toilettage vert d''eau aux lumières dorées. L''animal de la photo est sur la table pendant qu''une toiletteuse le sèche au séchoir ; son poil gonfle.","dur":10},{"text":"Son pelage devient une énorme boule de poils parfaitement ronde, un nœud papillon au cou ; la toiletteuse et les clients le regardent, stupéfaits. Ton de comédie.","dur":10}]',
 '1080p', '16:9', 1, 'Une photo de votre animal', 100, 1, unixepoch() * 1000),
('prepare-toi', 'Prépare-toi avec moi', 'La routine du matin, de la serviette à la tenue du jour, en vertical', 'mode', 'templates/prepare-toi/video.mp4', 'Photo verticale dans une chambre claire avec un grand miroir et des plantes : la personne de la photo en peignoir blanc, serviette sur la tête, face caméra. Garder son visage.', 'flux-3-max',
 '[{"text":"Vidéo verticale « prépare-toi avec moi » dans une chambre claire avec un grand miroir et des plantes. La personne de la photo, en peignoir et serviette sur la tête, se soigne la peau, enlève la serviette, puis réapparaît habillée d''un blazer crème et envoie un baiser à la caméra.","dur":12}]',
 '1080p', '9:16', 1, 'Une photo de la personne', 110, 1, unixepoch() * 1000),
('danse-tendance', 'Danse tendance', 'Une petite chorégraphie en vertical dans une pièce lumineuse', 'mode', 'templates/danse-tendance/video.mp4', 'Photo verticale en pied dans une pièce blanche et lumineuse : la personne de la photo en haut blanc et pantalon large gris, face caméra. Garder son visage.', 'flux-3-max',
 '[{"text":"Vidéo verticale dans une pièce blanche et lumineuse. La personne de la photo, en haut blanc et pantalon large gris, fait face à la caméra puis enchaîne une courte chorégraphie tendance, tourne sur elle-même, cheveux qui volent. Plan fixe en pied.","dur":8}]',
 '1080p', '9:16', 1, 'Une photo de la personne', 120, 1, unixepoch() * 1000),
('changement-look', 'Changement de look', 'Sur le quai, un train passe et la tenue change', 'mode', 'templates/changement-look/video.mp4', 'Photo verticale en pied sur un quai de gare : la personne de la photo, casquette et t-shirt jaune, face caméra. Garder son visage.', 'kling-4',
 '[{"text":"Vidéo verticale sur un quai de gare. La personne de la photo, casquette et t-shirt jaune, se tient face à la caméra ; un train passe à toute vitesse devant elle.","dur":5},{"text":"Quand le train est passé, elle porte une nouvelle tenue : polo rayé rose et turquoise et casquette marine, et pose fièrement. Même cadrage, plan fixe.","dur":5}]',
 '1080p', '9:16', 1, 'Une photo de la personne', 130, 1, unixepoch() * 1000),
('lookbook-rue', 'Lookbook urbain', 'Votre collection portée dans les rues de New York, en trois plans', 'mode', 'templates/lookbook-rue/video.mp4', 'Photo de campagne de mode : un mannequin porte le vêtement de la photo dans une rue de New York mouillée, taxi jaune, couleurs franches. Garder le vêtement exactement tel quel.', 'kling-4',
 '[{"text":"Gros plan sur le vêtement de la photo porté par un mannequin devant un rideau de fer couvert de graffitis.","dur":5},{"text":"Trois amis portant la collection marchent vers la caméra dans une rue de New York mouillée, taxi jaune garé, ralenti.","dur":5},{"text":"Ils posent sur le perron d''un immeuble en brique, regard caméra. Image de campagne de mode, couleurs franches.","dur":5}]',
 '1080p', '16:9', 1, 'Une photo de votre vêtement', 140, 1, unixepoch() * 1000),
('visite-maison', 'Visite de maison', 'Une visite fluide d''une maison, de la terrasse à la cuisine', 'immobilier', 'templates/visite-maison/video.mp4', 'Photo immobilière de la pièce de la photo, depuis la terrasse ensoleillée, lumière chaude de fin de journée, cadrage large et droit. Garder la pièce telle quelle.', 'kling-4',
 '[{"text":"Visite immobilière en un plan-séquence : la caméra avance lentement depuis la terrasse ensoleillée vers l''intérieur de la pièce de la photo, passe devant la table et termine sur la cuisine en bois. Lumière chaude de fin de journée, mouvement fluide et stable.","dur":10}]',
 '1080p', '16:9', 1, 'Une photo de la pièce', 150, 1, unixepoch() * 1000),
('architecture', 'Architecture en mouvement', 'Des détails au plan large : un bâtiment mis en valeur', 'immobilier', 'templates/architecture/video.mp4', 'Photo d''architecture du bâtiment de la photo en plan large, ciel bleu, passants sur l''esplanade, lignes droites. Garder le bâtiment tel quel.', 'kling-4',
 '[{"text":"Film d''architecture : gros plans sur une rambarde et une façade vitrée, puis la caméra recule et révèle le bâtiment de la photo en entier, passants sur l''esplanade, ciel bleu. Mouvements de drone lents et élégants.","dur":15}]',
 '1080p', '16:9', 1, 'Une photo du bâtiment', 160, 1, unixepoch() * 1000),
('histoire-papier', 'Histoire en papier découpé', 'Un récit historique raconté en papier découpé, avec voix off', 'explication', 'templates/histoire-papier/video.mp4', 'Décor en papier découpé sur un vieux parchemin éclairé par une lanterne : une mer de vagues en papier bleu, une barque avec un buste de Jules César. Texture de papier.', 'wan-3',
 '[{"text":"Animation en papier découpé sur un vieux parchemin éclairé par une lanterne : une mer de vagues en papier bleu, une barque avance avec un buste de Jules César, des pirates en silhouettes noires brandissent leurs sabres, un point d''interrogation rouge apparaît. Une voix off raconte : « À 25 ans, Jules César a été enlevé par des pirates. » Texture de papier, mouvements saccadés image par image.","dur":10}]',
 '1080p', '16:9', 1, NULL, 170, 1, unixepoch() * 1000),
('mythologie-affiches', 'Mythologie en affiches', 'Trois dieux grecs en affiches animées, style vectoriel', 'explication', 'templates/mythologie-affiches/video.mp4', 'Affiche vectorielle en trois panneaux côte à côte, bleu nuit, turquoise et bordeaux, avec trois dieux grecs drapés et des orbes lumineux, aplats de couleur.', 'wan-3',
 '[{"text":"Animation vectorielle façon affiche : trois panneaux côte à côte, bleu nuit, turquoise et bordeaux, avec trois dieux grecs drapés. Le premier lance un éclair, le deuxième fait surgir des vagues et brandit un trident, le troisième s''efface dans des rideaux de velours. Orbes lumineux, aplats de couleur, mouvements lents. Voix off qui présente Zeus, Poséidon et Hadès.","dur":30}]',
 '720p', '16:9', 1, NULL, 180, 1, unixepoch() * 1000);
